+import { useWorkspaceStore } from '../../store/useWorkspaceStore';
+
+export default function Notebook() {
+  const { 
+    notebook, 
+    setNotebookCover, 
+    setNotebookPin, 
+    unlockNotebook, 
+    lockNotebook, 
+    nextPage, 
+    prevPage, 
